# NIKKO-ENV-KEY: the key used to be a literal on this line. Read from .env now.
# os is imported locally so this does not depend on import order anywhere above it.
def _load_env():
    import os as _o
    _p = _o.path.join(_o.path.dirname(_o.path.abspath(__file__)), ".env")
    try:
        with open(_p, encoding="utf-8") as _f:
            for _line in _f:
                _line = _line.strip()
                if not _line or _line.startswith("#") or "=" not in _line:
                    continue
                _k, _v = _line.split("=", 1)
                _o.environ.setdefault(_k.strip(), _v.strip().strip('"').strip("'"))
    except FileNotFoundError:
        pass
    except Exception as _e:
        print("[env] could not read .env: %s" % _e)
_load_env()
