        _ars_z = _zc_am(df['_hr_matchup_boost']) if '_hr_matchup_boost' in df.columns else pd.Series(0.0, index=df.index)
        _ap = _ars_z.clip(lower=0); _mp = _arm_z.clip(lower=0)
