        # same bands as the original pd.cut so the pool floor works.
        _hvb2 = pd.to_numeric(df['hr_value'], errors='coerce').fillna(0)
        df['hr_value_confluence'] = pd.cut(
            _hvb2, bins=[-1.0, 0.0001, 60.0, 80.0, 92.0, 101.0],
            labels=["\U0001F53B No Floor", "\u2796 Spot Light", "\u2795 Solid Value Spot",
                    "\u2705 Good Value Spot", "\U0001F3AF Prime Value Spot"]).astype(str)
