        if st.session_state.get('hr_calibrate', True) and _cal_p:
            import json as _json
            _cal = _json.load(open(_cal_p))
            _anch = _cal.get("anchors", [])
            if len(_anch) >= 2:
                _xs = [float(_a[0]) / 100.0 for _a in _anch]
                _ys = [float(_a[1]) / 100.0 for _a in _anch]
                def _calib_one(_p):
                    if _p <= _xs[0]:
                        return (_ys[0] * (_p / _xs[0])) if _xs[0] > 0 else _ys[0]
