def _tl_write(_tl_msg):
    """print() does NOT survive a streamlit render.  Measured 2026-09-05:
    logs/site_*.log held 98 lines of streamlit banner and ZERO [bandlane],
    [export] or [drawtwin] lines after eight page loads.  readchips already
    worked around this by writing its own file -- do the same, and print too
    in case anything is listening."""
    import os as _tl_os
    try:
        _tl_root = _tl_os.path.dirname(_tl_os.path.abspath(__file__))
    except Exception:
        _tl_root = _tl_os.path.expanduser("~/mlb_analytics")
    for _tl_p2 in (_tl_os.path.join(_tl_root, "nk", "history", "traceloss.log"),
                   "/tmp/traceloss.log"):
        try:
            _tl_d2 = _tl_os.path.dirname(_tl_p2)
            if _tl_d2 and not _tl_os.path.isdir(_tl_d2):
                _tl_os.makedirs(_tl_d2, exist_ok=True)
            with open(_tl_p2, "a") as _tl_fh:
                _tl_fh.write(_tl_msg + chr(10))
        except Exception:
            pass
    try:
        print(_tl_msg)
    except Exception:
        pass


def _tl_say(_tl_where, _tl_f):
    try:
        import datetime as _tl_dt
        _tl_p = []
        for _tl_c in _tl_cols:
            if _tl_c not in getattr(_tl_f, "columns", ()):
                _tl_p.append("%s ABSENT" % _tl_c)
                continue
            try:
                _tl_s = pd.to_numeric(_tl_f[_tl_c], errors="coerce")
                _tl_p.append("%s %d/%d" % (_tl_c, int(_tl_s.notna().sum()),
                                           len(_tl_f)))
            except Exception:
                _tl_p.append("%s ?" % _tl_c)
        _tl_write("[traceloss] %s %-11s idx=%s  %s"
                  % (_tl_dt.datetime.now().strftime("%H:%M:%S"), _tl_where,
                     "contiguous" if list(_tl_f.index) == list(range(len(_tl_f)))
                     else "SLICED",
                     "  ".join(_tl_p)))
    except Exception as _tl_e:
        try:
            _tl_write("[traceloss] %s skipped: %s" % (_tl_where, _tl_e))
        except Exception:
            pass


