def _american_from_prob(p):
    p = min(max(p, 0.01), 0.99)
    return -round(p/(1-p)*100) if p >= 0.5 else round((1-p)/p*100)

def _decimal_from_prob(p):
    p = min(max(p, 0.01), 0.99)
    return 1.0 / p

