def stat_reference():   # NIKKO-REF-MEASURED
    """Every threshold measured band-by-band on 5959 bat-games / 24 graded nights.
    Nothing here is carried over from older docs. Where a signal has never been saved to the
    boards it says so instead of repeating an unverified number."""


# ── REUSABLE: all-prop confluence lookup card (used in Full Data, Live Tracker, Calibration) ──
def confluence_lookup(source_df, key, label="🔍 Player name",
                      placeholder="e.g. Soto, Caglianone, Witt..."):
    """Type a name → show that batter's confluences across all 3 props. Persists after game start."""
    search = st.text_input(label, placeholder=placeholder, key=key)
    if not search:
        return
    match = source_df[source_df['name'].str.contains(search, case=False, na=False)].copy()
    if match.empty:
        st.info(f"No batter matching '{search}' on today's slate.")
        return
    # NIKKO-LOOKUP-LOCK: the docstring and the Full Data caption both promise these confluences
    # survive first pitch. Nothing was actually locking them -- once a game starts the frame
    # recomputes and every matchup-dependent confluence goes NaN, so the card printed dashes.
    # boards/boards_TODAY.csv was written pre-game with them intact, so fill ONLY the blanks
    # from it. Live values always win; nothing is overwritten with stale data.
    try:
        _lk_path = 'boards/boards_%s.csv' % TODAY
        if os.path.exists(_lk_path) and 'player_id' in match.columns:
            _lk = pd.read_csv(_lk_path)
            if 'player_id' in _lk.columns:
                _lk['player_id'] = pd.to_numeric(_lk['player_id'], errors='coerce')
                _lk = _lk.dropna(subset=['player_id']).drop_duplicates('player_id').set_index('player_id')
                _lk_cols = [c for c in _lk.columns
                            if ('confluence' in c or 'edges' in c or 'edge_n' in c
                                or c.endswith('_tier') or c.endswith('_score'))]
                _filled = 0
                for _i in match.index:
                    try:
                        _pid = float(match.at[_i, 'player_id'])
                    except Exception:
                        continue
                    if _pid not in _lk.index: continue
                    for _c in _lk_cols:
                        _v = match.at[_i, _c] if _c in match.columns else None
                        _blank = (_v is None) or (isinstance(_v, float) and pd.isna(_v)) \
                                 or (isinstance(_v, str) and _v.strip() in ('', '-', '\u2014'))
                        if _blank:
                            match.at[_i, _c] = _lk.at[_pid, _c]
                            _filled += 1
                if _filled:
                    st.caption('\u2139\ufe0f showing the slate-time values for %d field(s) \u2014 '
                               'this game is underway and the live frame no longer carries them' % _filled)
    except Exception:
        pass   # lookup must never break on a missing or malformed snapshot
    for _, r in match.iterrows():
        nm = r['name']
        team = r.get('team_abbrev', '?'); opp = r.get('opponent', '?')
        sp = r.get('opp_pitcher', '?'); stt = r.get('status', '')
        gst = r.get('game_state', 'Preview')
        gtag = {'Preview':'🕐 upcoming','Live':'🔴 LIVE','Final':'🏁 final'}.get(gst, '')
        st.markdown(f"### {nm}  ·  {team} vs {opp}")
        st.caption(f"facing {sp}  ·  {stt}  ·  {gtag}")
        php = r.get('p_hr_per_9', None); pxslg = r.get('p_xslg_allowed', None); pk9 = r.get('p_k_per_9', None)
        pieces = []
        if php is not None: pieces.append(f"P HR/9: **{php:.2f}**" + (" 🔥" if php>=1.30 else ""))
        if pk9 is not None: pieces.append(f"P K/9: **{pk9:.1f}**" + (" 🧊" if pk9<=7.8 else ""))
        if pxslg is not None: pieces.append(f"P xSLG-allow: **{pxslg:.3f}**" + (" 💥" if pxslg>=0.420 else ""))
        if 'pen_threat' in r and r.get('pen_threat'): pieces.append(f"{r.get('pen_threat','')}")
        if pieces: st.markdown("**Pitcher (the #1 signal):**  " + "  ·  ".join(pieces))
        c1, c2, c3 = st.columns(3)
        with c1:
            st.markdown("**🟥 HOME RUN**")
            st.markdown(f"{r.get('hr_confluence_tier','—')}")
            st.caption(f"score {r.get('hr_score',0):.0f} · {int(r.get('hr_edge_n',0))} signals")
            st.markdown(r.get('hr_edges','—') or '—')
            st.caption(f"Value: {r.get('hr_value_confluence','—')} · {r.get('hr_value_edges','') or '—'}")
        with c2:
            st.markdown("**🟩 1.5 TB**")
            st.markdown(f"{r.get('tb15_confluence','—')}")
            st.caption(f"score {r.get('tb_score',0):.0f} · {int(r.get('tb15_edge_n',0))} signals")
            st.markdown(r.get('tb15_edges','—') or '—')
        with c3:
            st.markdown("**🟦 2.5 TB**")
            st.markdown(f"{r.get('tb25_confluence','—')}")
            st.caption(f"score {r.get('sleeper_score',0):.0f} · {int(r.get('tb25_edge_n',0))} signals")
            st.markdown(r.get('tb25_edges','—') or '—')
        st.caption(f"BA {r.get('ba','—')} · xISO {r.get('xiso','—')} · barrel {r.get('brl_percent','—')}% · "
                   f"hard-hit {r.get('hard_hit_percent','—')}% · zone-fit {r.get('pitch_vuln_score','—')}")
        st.markdown("---")

